using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEditor.Rendering;using UnityEngine;using UnityEngine.Rendering;
public static class Native49ParticleCompile {
 static string Hash(string p)=>BitConverter.ToString(System.Security.Cryptography.SHA256.Create().ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();
 public static string Run(){
  if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Stopped ready49required");
  string stage="Builds/URPMigration/ParticleNativeCompile-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ");Directory.CreateDirectory(stage);File.Copy("Tools/URPMigration/Native49ParticleCompile.cs",stage+"/Native49ParticleCompile.cs");var packet=JObject.Parse(File.ReadAllText("Tools/URPMigration/ParticleCandidates-current.json")).Value<string>("stage");var rows=new JArray();Shader shader=null;
  try{foreach(string file in new[]{"LegacyParticleAdditive.shader","LegacyParticleAlpha.shader","LegacyParticlePremultiply.shader","ParticlesStandardUnlitRGB.shader","ParticlesLitSourceRGBA.shader"}){
   var path=packet+"/"+file;shader=ShaderUtil.CreateShaderAsset(File.ReadAllText(path),false);shader.hideFlags=HideFlags.HideAndDontSave;var pass=ShaderUtil.GetShaderData(shader).GetSubshader(0).GetPass(0);File.WriteAllText(stage+"/"+file+".native.hlsl",pass.SourceCode);
   string[][] sets=file.StartsWith("Legacy")?new[]{Array.Empty<string>(),new[]{"SOFTPARTICLES_ON"}}:file.Contains("Unlit")?new[]{new[]{"_SURFACE_TYPE_TRANSPARENT"},new[]{"_SURFACE_TYPE_TRANSPARENT","_EMISSION","_FADING_ON","_FLIPBOOKBLENDING_ON","_SOFTPARTICLES_ON"},new[]{"_SURFACE_TYPE_TRANSPARENT","_NORMALMAP","_DISTORTION_ON","_FADING_ON","_SOFTPARTICLES_ON","_COLOROVERLAY_ON"}}:new[]{new[]{"_SURFACE_TYPE_TRANSPARENT","_FADING_ON","_FLIPBOOKBLENDING_ON","_SOFTPARTICLES_ON","_ADDITIONAL_LIGHTS","_LIGHT_FALLOFF_LINEAR"},new[]{"_ALPHATEST_ON","_EMISSION","_ADDITIONAL_LIGHTS","_LIGHT_FALLOFF_LINEAR"}};
   foreach(var set in sets)foreach(var xr in new[]{Array.Empty<string>(),new[]{"INSTANCING_ON","STEREO_MULTIVIEW_ON"},new[]{"INSTANCING_ON","STEREO_INSTANCING_ON"}})foreach(var type in new[]{ShaderType.Vertex,ShaderType.Fragment}){
    var keys=set.Concat(xr).ToArray();var result=pass.CompileVariant(type,keys,ShaderCompilerPlatform.GLES3x,BuildTarget.Android,GraphicsTier.Tier3,true);var data=result.ShaderData??Array.Empty<byte>();var name="program-"+rows.Count.ToString("D3")+".bin";File.WriteAllBytes(stage+"/"+name,data);rows.Add(new JObject{["candidate"]=path,["candidateSHA256"]=Hash(path),["pass"]=pass.Name,["type"]=type.ToString(),["platform"]="GLES3x",["keywords"]=new JArray(keys),["success"]=result.Success,["hasStage"]=pass.HasShaderStage(type),["bytes"]=data.Length,["output"]=name,["messages"]=new JArray(result.Messages.Select(m=>new JObject{["severity"]=m.severity.ToString(),["message"]=m.message,["file"]=m.file,["line"]=m.line}))});
   }UnityEngine.Object.DestroyImmediate(shader);shader=null;
  }}finally{if(shader!=null)UnityEngine.Object.DestroyImmediate(shader);File.WriteAllText(stage+"/report.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["target"]="Android/Tier3/GLES3x",["packetManifest"]=packet+"/manifest.json",["packetSHA256"]=Hash(packet+"/manifest.json"),["rows"]=rows,["failed"]=rows.Count(r=>!(bool)r["success"]||!(bool)r["hasStage"]||(int)r["bytes"]==0),["limits"]="Native outside-Assets selected five source-derived particle families; actual reachable alpha/emission/flipbook/normal/distortion/soft-depth and particle-point Surface vertex branches plus XR instancing. Authored fog disabled and MSAA1. Frame/lifecycle/opaque versus GrabPass composition/cold actual Main/player/Quest remain separate. No unsupported D3D+Android external requests."}.ToString());}
  if(rows.Any(r=>!(bool)r["success"]||!(bool)r["hasStage"]||(int)r["bytes"]==0))throw new Exception("Particle native compilation gate failed "+stage);return Path.GetFullPath(stage+"/report.json");
 }
}
